#ifndef CSM_TUI_H
#define CSM_TUI_H

#include <stddef.h>

#include "field.h"
#include "github.h"
#include "inventory.h"
#include "report.h"
#include "screen.h"
#include "session.h"
#include "settings.h"
#include "term.h"
#include "theme.h"
#include "trash.h"
#include "uistate.h"

/* Columns of the list. */
#define TUI_COLUMNS 5

/* Columns of the session table; the last one, the first prompt, flexes. */
#define TUI_SESSION_COLUMNS 6

/* Columns of the trash list: entry, removed, size, project. */
#define TRASH_COLUMNS 4

#define TUI_MAX_BUTTONS 10

#define TUI_GAP 2		/* columns between table columns */
#define TUI_MARK 2		/* the column of marks before a list row */

/* The list columns in screen order; sorting goes by one of them. */
enum tui_sort {
	SORT_STATE,
	SORT_PROJECT,
	SORT_SESSIONS,
	SORT_SIZE,
	SORT_MODIFIED
};

enum tui_focus {
	FOCUS_LIST,
	FOCUS_DETAILS
};

enum tui_screen {
	SCREEN_LIST,		/* session directories */
	SCREEN_TRASH,
	SCREEN_SETTINGS,
	SCREEN_HELP
};

/* The rows of the settings screen. */
enum tui_option {
	OPTION_THEME,
	OPTION_COUNT
};

enum tui_mode {
	MODE_BROWSE,
	MODE_FILTER,		/* the filter field takes the keys */
	MODE_FIELD,		/* the path field of Move or Fix */
	MODE_PLAN		/* the preview of a change, until Enter or Esc */
};

enum tui_action {
	ACTION_NONE,
	ACTION_MOVE,
	ACTION_FIX,
	ACTION_REMOVE,
	ACTION_PRUNE,		/* githubRepoPaths that no longer exist */
	ACTION_RESTORE,
	ACTION_DELETE		/* from the trash, for good */
};

/* The texts of one list row, made once per scan. */
struct tui_row {
	char *cell[TUI_COLUMNS];
};

/* The sessions of one directory, read when it is first selected. */
struct tui_details {
	int loaded;
	size_t count;
	char **cells;		/* count rows of TUI_SESSION_COLUMNS */
	size_t widths[TUI_SESSION_COLUMNS];
};

/* The trash, read when its screen opens and after each change. */
struct tui_trash {
	char *path;		/* NULL when the home directory is unknown */
	struct trash_entry *entries;
	size_t count;
	char **cells;		/* count rows of TRASH_COLUMNS */
	size_t widths[TRASH_COLUMNS];
	char *marked;
	size_t cursor, top;
	unsigned long long total;
};

/* A button of the bar and where the last frame drew it. */
struct tui_button {
	struct key key;
	const char *keytext;	/* "m", "Enter" */
	const char *label;	/* catalogue key */
	const char *why;	/* NULL when it works now, else the reason */
	size_t x0, x1;
};

struct tui {
	struct claude_paths paths;
	struct inventory inv;
	struct tui_row *rows;
	struct tui_details *details;
	size_t widths[TUI_COLUMNS];	/* widest cell of each list column */
	size_t *view;		/* directories shown, filtered and sorted */
	size_t view_count;
	char *marked;		/* per directory: chosen with Space or a click */
	size_t anchor;		/* where a Shift-click range starts, in view */
	size_t cursor, top;	/* positions in view */
	size_t detail_cursor, detail_top;
	int list_follow, detail_follow;	/* the frame scrolls to the cursor */
	enum tui_sort sort;
	int reverse;
	char filter[256];
	enum tui_screen screen;
	enum tui_mode mode;
	enum tui_focus focus;
	size_t split;		/* the list's share of the panels, in 1/1000 */
	int claude;		/* Claude Code runs: changes are blocked */
	int check_claude;	/* look again before the next frame */
	int (*claude_now)(void);	/* the look right before a change */
	char *claude_error;
	size_t github_dead;	/* githubRepoPaths that no longer exist */
	char *version_warning;	/* another Claude Code version; NULL when not */
	char *error;		/* the result of the last key, until the next */
	char *warning;
	char *info;
	int quit;

	struct tui_trash trash;

	enum tui_screen help_back;	/* the screen help came from */
	char **help_lines;	/* the general help wrapped to help_width */
	size_t help_count, help_width, help_top, help_rows;

	struct settings settings;
	char *settings_path;	/* NULL when the home directory is unknown */
	char *state_path;	/* likewise */
	char *state_saved;	/* the state as last read or written */
	size_t option;		/* the chosen row of the settings screen */
	int color;		/* 0 under NO_COLOR: no colours, no themes */
	int background;		/* the terminal's: 1 dark, 0 light, -1 unknown */
	int answered;		/* the terminal told its background */

	/* The change being prepared. */
	enum tui_action action;
	char *action_path;	/* the project moved or fixed */
	size_t *targets;	/* directories or trash entries it is for */
	size_t target_count;
	struct field field;
	char **candidates;	/* where a fixed project may be now */
	size_t candidate_count;
	char **suggest;		/* shown under the field */
	size_t suggest_count, suggest_cursor, suggest_top;
	int completing;		/* suggest holds Tab completions */
	struct report preview;
	size_t preview_top;
	int confirm;		/* No and Yes in an alert in the middle */
	int yes;		/* Yes has the focus */

	/* What the last frame drew where, for the mouse. */
	size_t list_y, list_rows;	/* the header, then the rows */
	size_t sep_y, body_rows;
	size_t lower_y, lower_rows;
	size_t table_y, detail_rows;	/* the session rows */
	size_t items_y;		/* the first suggestion or preview line */
	size_t col_x[TUI_COLUMNS], col_w[TUI_COLUMNS];
	size_t buttons_y, status_y;
	size_t answers_y, no_x0, no_x1, yes_x0, yes_x1;
	size_t value_x0, value_x1;	/* the column of the settings' values */
	struct tui_button buttons[TUI_MAX_BUTTONS];
	size_t button_count;
	int dragging;		/* the panel border follows the mouse */
	long click_ms;		/* the last click, for a double one */
	size_t click_x, click_y;
};

void tui_fit_columns(const size_t *natural, size_t count, size_t flex,
    const size_t *drop, size_t drops, size_t total, size_t *out);
int tui_match(const char *text, const char *filter);
void tui_init(struct tui *t);
void tui_scan(struct tui *t);
void tui_set_claude(struct tui *t, int running, int err);
void tui_key(struct tui *t, const struct key *k);
long tui_wanted(const struct tui *t);
void tui_load(struct tui *t, size_t dir);
void tui_render(struct tui *t, struct screen *s);
void tui_free(struct tui *t);
int tui_state_changed(const struct tui *t);
void tui_save_state(struct tui *t);
int tui_run(void);

/* Shared by tui.c and tui_draw.c. */
extern const char *const tui_session_headers[TUI_SESSION_COLUMNS];
size_t tui_selected(const struct tui *t);
void tui_make_buttons(struct tui *t);
size_t tui_list_rows(const struct tui *t, size_t body);
int tui_dark(const struct tui *t);
const struct theme_colors *tui_theme(const struct tui *t);
size_t tui_choices(enum tui_option option);
size_t tui_choice(const struct tui *t, enum tui_option option);
const char *tui_why_option(const struct tui *t, enum tui_option option);
char *tui_state_text(const struct tui *t);

#endif
